// Lighting rig for the hero objects: the real-time twin of the Cycles poster setup in
// tools/objects/common.py (ADR-0005 §3: the object in the page must read like its render).
//
//   import { createRig, RIG } from './objects/rig.js';
//   const rig = createRig(THREE, renderer, scene, { accent: '#bbed26' });
//   rig.prepare(gltf.scene);          // shadows, glass fixes, backlight from the GLB's stage
//   rig.frameCamera(camera, gltf.scene);  // the poster's camera (from the GLB's stage)
//   // each frame, before renderer.render(scene, camera):
//   rig.update();                      // re-renders the contact shadow (skip if nothing moved)
//
// Same values as the posters: one studio HDRI (embedded below, PMREM-filtered), a warm key and
// a rim in the section's colour as directional lights with the poster's sun strengths, Khronos
// PBR Neutral tone mapping at the same exposure, and a ground that only darkens (key shadow +
// a blurred contact shadow), so it sits on the page's #0A0A0B like the poster's shadow catcher.
// Options: accent (rim colour), background (default true: scene.background = ground colour;
// false leaves the canvas transparent over the page), contact (default true), keyShadow
// (default true), shadowMapSize (default 1024), exposure (overrides RIG.exposure).

/* RIG:BEGIN (generated by tools/objects/make_env.py from rig.json; do not edit) */
export const RIG = {"ground":"#0A0A0B","camera":{"fov":24,"position":[0,1.55,8.4],"target":[0,0.92,0]},"fit":{"size":2.15,"floor":0.0},"frame":{"fill":0.74},"backlight":{"intensity":0.8,"radius":1.0,"behind":1.3},"exposure":1.0,"toneMapping":"neutral","lights":{"key":{"from":[-0.55,0.78,0.5],"color":"#fff4e8","intensity":2.4,"angle":10},"rim":{"from":[0.62,0.42,-0.78],"intensity":5.0,"angle":6}},"env":{"width":256,"height":128,"base":{"top":0.035,"horizon":0.018,"bottom":0.006},"boxes":[{"name":"key softbox","dir":[-0.5,0.62,0.6],"w":46,"h":26,"intensity":3.2,"color":"#fff6ee"},{"name":"right strip","dir":[1.0,0.12,0.25],"w":10,"h":64,"intensity":2.2,"color":"#ffffff"},{"name":"left strip","dir":[-1.0,0.1,-0.35],"w":8,"h":56,"intensity":1.1,"color":"#eef2ff"},{"name":"top panel","dir":[0.1,1.0,-0.2],"w":34,"h":18,"intensity":1.4,"color":"#ffffff"}],"soft":3.0},"shadow":{"keyOpacity":0.4,"contactOpacity":0.85,"contactBlur":2.6,"contactFar":1.2}};
const STUDIO_HDR = '';
/* RIG:END */

function decodeRGBE(bytes) {
  // Minimal Radiance .hdr reader (new-style RLE and flat scanlines), enough for STUDIO_HDR.
  let pos = 0;
  const line = () => {
    let s = '';
    while (bytes[pos] !== 10) s += String.fromCharCode(bytes[pos++]);
    pos++;
    return s;
  };
  let l;
  while ((l = line()) !== '') if (pos >= bytes.length) throw new Error('bad hdr');
  const m = /-Y (\d+) \+X (\d+)/.exec(line());
  const h = +m[1], w = +m[2];
  const rgbe = new Uint8Array(w * h * 4);
  const scan = new Uint8Array(w * 4);
  for (let y = 0; y < h; y++) {
    if (bytes[pos] === 2 && bytes[pos + 1] === 2) {
      pos += 4;
      for (let c = 0; c < 4; c++) {
        let x = 0;
        while (x < w) {
          let n = bytes[pos++];
          if (n > 128) {
            n -= 128;
            const v = bytes[pos++];
            while (n--) scan[(x++) * 4 + c] = v;
          } else {
            while (n--) scan[(x++) * 4 + c] = bytes[pos++];
          }
        }
      }
    } else {
      scan.set(bytes.subarray(pos, pos + w * 4));
      pos += w * 4;
    }
    // file row 0 is the top; texture row 0 is the bottom (v = 0)
    rgbe.set(scan, (h - 1 - y) * w * 4);
  }
  const out = new Float32Array(w * h * 4);
  for (let i = 0; i < w * h; i++) {
    const e = rgbe[i * 4 + 3];
    const f = e ? Math.pow(2, e - 136) : 0;
    out[i * 4] = rgbe[i * 4] * f;
    out[i * 4 + 1] = rgbe[i * 4 + 1] * f;
    out[i * 4 + 2] = rgbe[i * 4 + 2] * f;
    out[i * 4 + 3] = 1;
  }
  return { w, h, data: out };
}

function studioTexture(THREE) {
  const bin = atob(STUDIO_HDR);
  const bytes = new Uint8Array(bin.length);
  for (let i = 0; i < bin.length; i++) bytes[i] = bin.charCodeAt(i);
  const { w, h, data } = decodeRGBE(bytes);
  const half = new Uint16Array(data.length);
  for (let i = 0; i < data.length; i++) half[i] = THREE.DataUtils.toHalfFloat(data[i]);
  const tex = new THREE.DataTexture(half, w, h, THREE.RGBAFormat, THREE.HalfFloatType);
  tex.mapping = THREE.EquirectangularReflectionMapping;
  tex.colorSpace = THREE.LinearSRGBColorSpace;
  tex.magFilter = tex.minFilter = THREE.LinearFilter;
  tex.generateMipmaps = false;
  tex.needsUpdate = true;
  return tex;
}

const BLUR_VERT = 'varying vec2 vUv; void main(){ vUv = uv; gl_Position = vec4(position.xy, 0.0, 1.0); }';
const BLUR_FRAG = `
  uniform sampler2D tDiffuse; uniform vec2 dir; varying vec2 vUv;
  void main(){
    vec4 s = texture2D(tDiffuse, vUv) * 0.2270270270;
    s += texture2D(tDiffuse, vUv + dir * 1.3846153846) * 0.3162162162;
    s += texture2D(tDiffuse, vUv - dir * 1.3846153846) * 0.3162162162;
    s += texture2D(tDiffuse, vUv + dir * 3.2307692308) * 0.0702702703;
    s += texture2D(tDiffuse, vUv - dir * 3.2307692308) * 0.0702702703;
    gl_FragColor = s;
  }`;

function findStage(object) {
  // The GLB root node carries the poster's camera and backlight as extras ("stage").
  let st = null;
  object.traverse((o) => { if (!st && o.userData && o.userData.stage) st = o.userData.stage; });
  return st;
}

function contactShadow(THREE, renderer, scene, { size = 6, res = 512, far, blur, opacity, floor }) {
  // A blurred depth-from-below projection (the technique of drei's ContactShadows), standing in
  // for the occlusion the poster's shadow catcher gets from the studio environment.
  const group = new THREE.Group();
  group.position.y = floor + 0.002;
  const rtA = new THREE.WebGLRenderTarget(res, res, { type: THREE.HalfFloatType });
  const rtB = new THREE.WebGLRenderTarget(res, res, { type: THREE.HalfFloatType });
  rtA.texture.generateMipmaps = rtB.texture.generateMipmaps = false;
  const plane = new THREE.Mesh(
    new THREE.PlaneGeometry(size, size).rotateX(Math.PI / 2),
    new THREE.MeshBasicMaterial({ map: rtA.texture, transparent: true, opacity, depthWrite: false, toneMapped: false }),
  );
  plane.scale.y = -1;
  plane.renderOrder = -1;
  plane.userData.rigHelper = true;
  group.add(plane);
  const cam = new THREE.OrthographicCamera(-size / 2, size / 2, size / 2, -size / 2, 0, far);
  cam.rotation.x = Math.PI / 2;
  group.add(cam);
  const depth = new THREE.MeshDepthMaterial();
  depth.depthTest = depth.depthWrite = false;
  depth.onBeforeCompile = (sh) => {
    sh.fragmentShader = sh.fragmentShader.replace(
      'vec4( vec3( 1.0 - fragCoordZ ), opacity );',
      'vec4( vec3( 0.0 ), ( 1.0 - fragCoordZ ) );',
    );
  };
  depth.side = THREE.DoubleSide;
  const blurMat = new THREE.ShaderMaterial({
    uniforms: { tDiffuse: { value: null }, dir: { value: new THREE.Vector2() } },
    vertexShader: BLUR_VERT,
    fragmentShader: BLUR_FRAG,
    depthTest: false,
    depthWrite: false,
  });
  const quad = new THREE.Mesh(new THREE.PlaneGeometry(2, 2), blurMat);
  const quadScene = new THREE.Scene();
  quadScene.add(quad);
  const quadCam = new THREE.OrthographicCamera(-1, 1, 1, -1, 0, 1);

  function pass(src, dst, dx, dy) {
    blurMat.uniforms.tDiffuse.value = src.texture;
    blurMat.uniforms.dir.value.set(dx / res, dy / res);
    renderer.setRenderTarget(dst);
    renderer.render(quadScene, quadCam);
  }

  function update() {
    const bg = scene.background, ov = scene.overrideMaterial;
    const hidden = [];
    scene.traverse((o) => {
      if (o.visible && o.userData.rigHelper) { hidden.push(o); o.visible = false; }
    });
    const prevRT = renderer.getRenderTarget();
    const prevClear = renderer.getClearAlpha();
    const prevTM = renderer.toneMapping, prevShadow = renderer.shadowMap.autoUpdate;
    renderer.shadowMap.autoUpdate = false;
    renderer.toneMapping = THREE.NoToneMapping;
    scene.background = null;
    scene.overrideMaterial = depth;
    renderer.setClearAlpha(0);
    renderer.setRenderTarget(rtA);
    renderer.clear();
    renderer.render(scene, cam);
    scene.overrideMaterial = ov;
    pass(rtA, rtB, blur, 0);
    pass(rtB, rtA, 0, blur);
    pass(rtA, rtB, blur * 0.5, 0);
    pass(rtB, rtA, 0, blur * 0.5);
    renderer.setRenderTarget(prevRT);
    renderer.setClearAlpha(prevClear);
    renderer.toneMapping = prevTM;
    renderer.shadowMap.autoUpdate = prevShadow;
    scene.background = bg;
    hidden.forEach((o) => (o.visible = true));
  }

  function dispose() {
    rtA.dispose(); rtB.dispose(); depth.dispose(); blurMat.dispose();
    plane.geometry.dispose(); plane.material.dispose(); quad.geometry.dispose();
  }
  return { group, plane, update, dispose };
}

export function createRig(THREE, renderer, scene, opts = {}) {
  const accent = opts.accent ?? '#ffffff';
  const floor = RIG.fit.floor;
  const toV = (a) => new THREE.Vector3(a[0], a[1], a[2]).normalize();

  renderer.outputColorSpace = THREE.SRGBColorSpace;
  renderer.toneMapping = {
    neutral: THREE.NeutralToneMapping,
    agx: THREE.AgXToneMapping,
    aces: THREE.ACESFilmicToneMapping,
  }[RIG.toneMapping];
  renderer.toneMappingExposure = opts.exposure ?? RIG.exposure;
  renderer.shadowMap.enabled = true;
  renderer.shadowMap.type = THREE.VSMShadowMap;

  const pmrem = new THREE.PMREMGenerator(renderer);
  const hdr = studioTexture(THREE);
  const envRT = pmrem.fromEquirectangular(hdr);
  hdr.dispose();
  pmrem.dispose();
  scene.environment = envRT.texture;
  if (opts.background !== false) scene.background = new THREE.Color(RIG.ground);

  const root = new THREE.Group();
  root.name = 'rig';
  scene.add(root);

  const L = RIG.lights;
  const key = new THREE.DirectionalLight(L.key.color, L.key.intensity);
  key.position.copy(toV(L.key.from).multiplyScalar(8));
  key.castShadow = opts.keyShadow !== false;
  const sm = opts.shadowMapSize ?? 1024;
  key.shadow.mapSize.set(sm, sm);
  Object.assign(key.shadow.camera, { left: -2.6, right: 2.6, top: 2.6, bottom: -2.6, near: 1, far: 16 });
  key.shadow.radius = 10;
  key.shadow.blurSamples = 16;
  key.shadow.bias = -0.0005;
  root.add(key, key.target);

  let rimHex = accent;
  const rim = new THREE.DirectionalLight(accent, L.rim.intensity);
  rim.position.copy(toV(L.rim.from).multiplyScalar(8));
  root.add(rim, rim.target);

  const ground = new THREE.Mesh(
    new THREE.PlaneGeometry(20, 20).rotateX(-Math.PI / 2),
    new THREE.ShadowMaterial({ opacity: RIG.shadow.keyOpacity, depthWrite: false }),
  );
  ground.position.y = floor;
  ground.receiveShadow = true;
  ground.renderOrder = -2;
  ground.userData.rigHelper = true;
  root.add(ground);

  let contact = null;
  if (opts.contact !== false) {
    contact = contactShadow(THREE, renderer, scene, {
      far: RIG.shadow.contactFar,
      blur: RIG.shadow.contactBlur,
      opacity: RIG.shadow.contactOpacity,
      floor,
    });
    root.add(contact.group);
  }

  // Backlight: an accent disc behind the object drawn only into the transmission buffer, so it
  // is seen through glass and nowhere else (the Cycles twin is a plane visible to transmission
  // rays only). Emission = accent * intensity * (1 - (r/R)^2)^2, as in common.py.
  const glowTex = (() => {
    const n = 64, d = new Uint16Array(n * n * 4);
    for (let y = 0; y < n; y++) for (let x = 0; x < n; x++) {
      const r = Math.hypot((x + 0.5) / n * 2 - 1, (y + 0.5) / n * 2 - 1);
      const f = Math.max(0, 1 - r * r) ** 2, i = (y * n + x) * 4;
      d[i] = d[i + 1] = d[i + 2] = THREE.DataUtils.toHalfFloat(f);
      d[i + 3] = THREE.DataUtils.toHalfFloat(1);
    }
    const t = new THREE.DataTexture(d, n, n, THREE.RGBAFormat, THREE.HalfFloatType);
    t.magFilter = t.minFilter = THREE.LinearFilter;
    t.needsUpdate = true;
    return t;
  })();
  const glowMat = new THREE.MeshBasicMaterial({ map: glowTex, depthWrite: false, fog: false });
  const glow = new THREE.Mesh(new THREE.PlaneGeometry(2, 2), glowMat);
  glow.visible = false;
  glow.renderOrder = -3;
  glow.userData.rigHelper = true;
  root.add(glow);
  let mainTarget = null;
  const prevSceneHook = scene.onBeforeRender;
  scene.onBeforeRender = function (r, s, c, target) {
    mainTarget = target ?? null;
    if (prevSceneHook) prevSceneHook.call(this, r, s, c, target);
  };
  glow.onBeforeRender = (r) => {
    glowMat.colorWrite = r.getRenderTarget() !== mainTarget;
  };
  let glowIntensity = 0;
  const setGlowColor = (hex) => glowMat.color.set(hex).multiplyScalar(glowIntensity);

  function prepare(object) {
    object.traverse((o) => {
      if (!o.isMesh) return;
      o.castShadow = true;
      o.receiveShadow = false;
      const m = o.material;
      if (m && m.transmission > 0) {
        // glTF transmission renders a second pass; let the back faces show inside thick glass
        m.side = THREE.DoubleSide;
        m.shadowSide = THREE.FrontSide;
      }
    });
    const st = findStage(object);
    if (st && st.backlight) {
      const b = st.backlight;
      object.updateWorldMatrix(true, false);
      glow.position.fromArray(b.center);
      glow.scale.setScalar(b.radius);
      glow.lookAt(glow.position.clone().add(new THREE.Vector3().fromArray(b.normal)));
      glowIntensity = b.intensity;
      setGlowColor(rimHex);
      glow.visible = true;
    }
    stageOf = st || stageOf;
    return object;
  }

  let stageOf = null;
  function frameCamera(camera, object) {
    const c = (object && findStage(object)?.camera) || stageOf?.camera || RIG.camera;
    camera.fov = c.fov;
    camera.position.set(...c.position);
    camera.lookAt(new THREE.Vector3(...c.target));
    camera.updateProjectionMatrix();
    return camera;
  }

  return {
    key,
    rim,
    ground,
    contact,
    environment: envRT.texture,
    prepare,
    frameCamera,
    setAccent(hex) { rimHex = hex; rim.color.set(hex); setGlowColor(hex); },
    glow,
    update() { if (contact) contact.update(); },
    dispose() {
      envRT.dispose();
      contact?.dispose();
      ground.geometry.dispose();
      ground.material.dispose();
      glowTex.dispose();
      glowMat.dispose();
      glow.geometry.dispose();
      scene.onBeforeRender = prevSceneHook;
      scene.remove(root);
      if (scene.environment === envRT.texture) scene.environment = null;
    },
  };
}
